mapper.update:
UPDATE local_user_account
SET failed_attempts=#{failedAttempts}, locked_until=#{lockedUntil}, updated_at=#{updatedAt}
WHERE tenant_id=#{tenantId} AND id=#{id}

UPDATE local_user_account
SET failed_attempts=0, locked_until=NULL, updated_at=#{updatedAt}
WHERE tenant_id=#{tenantId} AND id=#{id}

UPDATE local_user_account
SET enabled=#{enabled}, roles_json=#{rolesJson}, version=version+1, updated_at=#{updatedAt}
WHERE tenant_id=#{tenantId} AND id=#{id} AND version=#{expectedVersion}

UPDATE local_user_account
SET password_hash=#{passwordHash}, failed_attempts=0, locked_until=NULL, version=version+1, updated_at=#{updatedAt}
WHERE tenant_id=#{tenantId} AND id=#{id} AND version=#{expectedVersion}

UPDATE local_user_account
SET mfa_enabled=#{mfaEnabled}, mfa_secret=#{mfaSecret}, version=version+1, updated_at=#{updatedAt}
WHERE tenant_id=#{tenantId} AND id=#{id} AND version=#{expectedVersion}

mapper.select:
SELECT token_hash, tenant_id, username, roles_json, created_at, expires_at, revoked_at
FROM local_auth_session
WHERE token_hash=#{tokenHash}

mapper.update:
UPDATE local_auth_session
SET revoked_at=#{revokedAt}
WHERE token_hash=#{tokenHash} AND revoked_at IS NULL

UPDATE local_auth_session
SET revoked_at=#{revokedAt}
WHERE tenant_id=#{tenantId} AND username=#{username} AND revoked_at IS NULL
